function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };
  const O = '#051428', Ink = '#0f1419';
  const Paper = '#f0e8d6', PaperDk = '#d4cbb4', PaperLt = '#fff8ea';
  const Red = '#c43c3c', RedDk = '#8a2020', Yellow = '#f4c020', Blue = '#335d92';

  // envelope body
  px(4, 8, 24, 18, O);
  px(5, 9, 22, 16, Paper);
  px(5, 9, 22, 1, PaperLt);
  px(5, 24, 22, 1, PaperDk);
  // flap V
  px(5, 9, 1, 8, PaperDk);
  px(26, 9, 1, 8, PaperDk);
  for (let i = 0; i < 11; i++) {
    px(5 + i, 9 + i, 1, 1, Blue);
    px(26 - i, 9 + i, 1, 1, Blue);
  }
  px(15, 19, 2, 1, Blue);
  // spam badge
  px(18, 4, 10, 10, O);
  px(19, 5, 8, 8, Red);
  px(19, 5, 8, 1, Yellow);
  px(22, 7, 2, 4, Yellow);
  px(22, 12, 2, 1, Yellow);
  // stamp
  px(7, 20, 5, 4, RedDk);
  px(8, 21, 3, 2, Red);
}
